import os
import re
import openai

def analyze_and_redact_unsafe_spans(text: str, api_key: str = None) -> dict:
    client = openai.OpenAI(api_key=api_key or os.environ.get("OPENAI_API_KEY"))

    segments = re.split(r'(?<=[.!?])\s+', text)
    redacted_segments = []
    unsafe_flags = []

    for segment in segments:
        stripped = segment.strip()
        if not stripped:
            redacted_segments.append(segment)
            continue

        response = client.moderations.create(
            model="text-moderation-latest",
            input=stripped
        )

        mod_result = response.results[0]
        if mod_result.flagged:
            redacted_segments.append("[REDACTED]")
            unsafe_flags.append({
                "span": stripped,
                "categories": mod_result.categories.model_dump()
            })
        else:
            redacted_segments.append(stripped)

    return {
        "redacted_text": " ".join(redacted_segments),
        "flagged_spans": unsafe_flags,
        "is_unsafe": bool(unsafe_flags)
    }
